add_filter( 'woocommerce_add_to_cart_sold_individually_found_in_cart', 'perfectpixel_sold_individually_message', 10 );

function perfectpixel_sold_individually_message( $found ) {
	if ( $found ) {
		// WooCommerce shows the exception message as an error; an empty message shows nothing.
		throw new Exception( esc_html( '{{sold_individually_text}}' ) );
	}
	return $found;
}
